import React, { useState, useEffect } from 'react';
import { useTheme } from '@mui/material/styles';
import { Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, CircularProgress } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import ApiRequest from 'utils/apiService';
import WarningIcon from '@mui/icons-material/Warning';

const DeleteAlert = ({ open, onClose, selectedIds, endpoint, onDeleteSuccess, message }) => {
    const theme = useTheme();
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(false);

    // ✅ Reset error when dialog opens
    useEffect(() => {
        if (open) {
            setError(null); // Clear error on dialog open
        }
    }, [open]);

    const handleDelete = async () => {
        try {
            setError(null);
            setLoading(true);
            await ApiRequest('DELETE', endpoint, { ids: selectedIds });
            onDeleteSuccess(); // Refresh the list on success
        } catch (error) {
            console.error('Delete failed:', error.message);
            setError(error.message || 'Failed to delete items. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            sx={{
                '& .MuiPaper-root': {
                    backgroundColor: theme.palette.text.primary // Change dialog background color
                }
            }}
            BackdropProps={{
                sx: {
                    backgroundColor: 'rgba(0, 0, 0, 0.5)' // Customize backdrop color (optional)
                }
            }}
        >
            <DialogTitle>
                Confirm Deletion
                <IconButton aria-label="close" onClick={onClose} sx={{ position: 'absolute', right: 8, top: 8 }}>
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent>
                <Alert severity="error" sx={{ color: theme.palette.primary.dark, background: theme.palette.primary.dark }}>
                    {message || `Are you sure you want to delete ${selectedIds.length > 1 ? 'these items' : 'this item'}?`}
                </Alert>
                {error && (
                    <Alert severity="error" sx={{ mt: 2 }}>
                        {error}
                    </Alert>
                )}
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose} color="secondary">
                    Cancel
                </Button>
                <Button onClick={handleDelete} color="error" variant="contained" disabled={loading}>
                    {loading ? <CircularProgress size={24} /> : 'Delete'}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default DeleteAlert;
